&lt;div class=&quot;presentation navmenudroite&quot;&gt;
&lt;h2 class=&quot;separator&quot;&gt;Les arch&#233;types de moine&lt;a class=&quot;headeranchor&quot; id=&quot;Les_arch&#233;types_de_moine_0&quot; href=&quot;#Les_arch&#233;types_de_moine_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&amp;nbsp;Retour &#224; la &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html&quot; title=&quot;Le moine&quot;&gt;classe&lt;/a&gt;.
&lt;ul style=&quot;margin-top:2px&quot;&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Adepte-Des-Armes-(Moine).html&quot; title=&quot;Adepte des armes&quot;&gt;Adepte des armes&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Adepte-Du-Feu-Serpent-(Moine).html&quot; title=&quot;Adepte du feu-serpent&quot;&gt;Adepte du feu-serpent&lt;/a&gt; (&lt;i&gt;OO&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Archer-Zen-(Moine).html&quot; title=&quot;Archer zen&quot;&gt;Archer zen&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Artiste-Martial-(Moine).html&quot; title=&quot;Artiste martial&quot;&gt;Artiste martial&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Aspic-Noir-(Moine).html&quot; title=&quot;Aspic noir&quot;&gt;Aspic noir&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Champion-Des-Poids-Plume-(Moine).html&quot; title=&quot;Champion des poids plume&quot;&gt;Champion des poids plume&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Halfelin.html&quot; title=&quot;Les halfelins&quot;&gt;Halfelin&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Chat-Sauvage-(Moine).html&quot; title=&quot;Chat sauvage&quot;&gt;Chat sauvage&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Disciple-Gris-(Moine).html&quot; title=&quot;Disciple gris&quot;&gt;Disciple gris&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Duergar-(Race).html&quot; title=&quot;Les duergars&quot;&gt;Duergar&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;&#201;l&#232;ve-De-La-Pierre-(Moine).html&quot; title=&quot;&#201;l&#232;ve de la pierre&quot;&gt;&#201;l&#232;ve de la pierre&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Or&#233;ade-(Race).html&quot; title=&quot;Les or&#233;ades&quot;&gt;Or&#233;ade&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Gardien-Agile-(Moine).html&quot; title=&quot;Gardien agile&quot;&gt;Gardien agile&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Homme-F&#233;lin-(Race).html&quot; title=&quot;Les hommes-f&#233;lins&quot;&gt;Homme-f&#233;lin&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Des-&#201;coles-(Moine).html&quot; title=&quot;Ma&#238;tre des &#233;coles&quot;&gt;Ma&#238;tre des &#233;coles&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Des-Katas-(Moine).html&quot; title=&quot;Ma&#238;tre des katas&quot;&gt;Ma&#238;tre des katas&lt;/a&gt; (MCA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Des-Manoeuvres-(Moine).html&quot; title=&quot;Ma&#238;tre des manoeuvres&quot;&gt;Ma&#238;tre des manœuvres&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Ma&#238;tre-Ivre-(Moine).html&quot; title=&quot;Ma&#238;tre ivre&quot;&gt;Ma&#238;tre ivre&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-&#192;-Peau-De-Fer-(Moine).html&quot; title=&quot;Moine &#224; peau de fer&quot;&gt;Moine &#224; peau de fer&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Hobgobelin-(Race).html&quot; title=&quot;Les hobgobelins&quot;&gt;Hobgobelin&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-De-La-Main-Qui-Gu&#233;rit-(Moine).html&quot; title=&quot;Moine de la main qui gu&#233;rit&quot;&gt; Moine de la main qui gu&#233;rit&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-De-La-Main-Vide-(Moine).html&quot; title=&quot;Moine de la main vide&quot;&gt;Moine de la main vide&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-De-La-Montagne-Sacr&#233;e-(Moine).html&quot; title=&quot;Moine de la montagne sacr&#233;e&quot;&gt;Moine de la montagne sacr&#233;e&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-Des-Cimes-(Moine).html&quot; title=&quot;Moine des cimes&quot;&gt;Moine des cimes&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Vanara-(Race).html&quot; title=&quot;Les vanaras&quot;&gt;Vanara&lt;/a&gt;) (MR)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-Des-Quatre-Vents-(Moine).html&quot; title=&quot;Moine des quatre vents&quot;&gt;Moine des quatre vents&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-Du-Fant&#244;me-Affam&#233;-(Moine).html&quot; title=&quot;Moine du fant&#244;me affam&#233;&quot;&gt; Moine du fant&#244;me affam&#233;&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-Du-Lotus-(Moine).html&quot; title=&quot;Moine du lotus&quot;&gt;Moine du lotus&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-Fluide-(Moine).html&quot; title=&quot;Moine fluide&quot;&gt;Moine fluide&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-Karmique-(Moine).html&quot; title=&quot;Moine karmique&quot;&gt;Moine karmique&lt;/a&gt; (AO)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Moine-Qinggong-(Moine).html&quot; title=&quot;Moine qinggong&quot;&gt;Moine qinggong&lt;/a&gt; (AM)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Mystique-Ki-(Moine).html&quot; title=&quot;Mystique ki&quot;&gt;Mystique ki&lt;/a&gt; (MJRA)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sage-Conseiller-(Moine).html&quot; title=&quot;Sage conseiller&quot;&gt;Sage conseiller&lt;/a&gt; (&lt;i&gt;UI&lt;/i&gt;)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sensei-(Moine).html&quot; title=&quot;Sensei&quot;&gt;Sensei&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sohei-(Moine).html&quot; title=&quot;Sohei&quot;&gt;Sohei&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Tetori-(Moine).html&quot; title=&quot;Tetori&quot;&gt;Tetori&lt;/a&gt; (AG)&lt;/li&gt;
  &lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Vagabond-(Moine).html&quot; title=&quot;Vagabond&quot;&gt;Vagabond&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Humain.html&quot; title=&quot;Les humains&quot;&gt;Humain&lt;/a&gt;) (MR)&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.LArt de la guerre (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Ultimate Combat/Art de la Guerre&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoUC.gif&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;&lt;i&gt;Le sohei est un ma&#238;tre des chevaux et de la chasse. Moine soldat, il se bat aussi bien &#224; pied qu’&#224; cheval. Il excelle au combat &#224; mains nues mais beaucoup privil&#233;gient les armes qu’ils peuvent manier en selle ou utiliser contre les chevaux adverses.&lt;/i&gt;&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Comp&#233;tences&lt;a class=&quot;headeranchor&quot; id=&quot;Comp&#233;tences_0&quot; href=&quot;#Comp&#233;tences_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Le sohei ajoute &lt;a class=&quot;pagelink&quot; href=&quot;Dressage.html&quot; title=&quot;Dressage&quot;&gt;Dressage&lt;/a&gt; &#224; ses comp&#233;tences de classe.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Armes et amures&lt;a class=&quot;headeranchor&quot; id=&quot;Armes_et_amures_1&quot; href=&quot;#Armes_et_amures_1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;&lt;div style=&quot;float:right; padding-left: 6px&quot;&gt;
&lt;table&gt;
&lt;tr style=&quot;vertical-align:bottom&quot;&gt;
&lt;td style=&quot;display:none; background-color: #f3efe2; border: 1px solid #4b3124; padding: 2px; text-align: left&quot;&gt;
&lt;table&gt;&lt;tr style=&quot;vertical-align: top&quot;&gt;&lt;td&gt;
&lt;b&gt;&lt;i&gt;&lt;u&gt;Ce texte a &#233;t&#233; modifi&#233; suite &#224; la FAQ suivante :&lt;/u&gt;&lt;br /&gt;&lt;br /&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Faq--Lart-De-La-Guerre.html#9&quot; title=&quot;FAQ de l&amp;#39;Art de la guerre&quot;&gt;→&lt;/a&gt; Moine, Sohei : Un sohei peut-il utiliser le d&#233;luge de coups en portant une armure l&#233;g&#232;re ?&lt;/i&gt;&lt;/b&gt;&lt;br /&gt;&lt;br /&gt;Oui (mais pas en portant une armure interm&#233;diaire ou lourde). En revanche, un &lt;u&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sohei-(Moine).html&quot; title=&quot;Sohei&quot;&gt;sohei&lt;/a&gt;&lt;/u&gt; ne b&#233;n&#233;ficie pas de sa capacit&#233; de moine bonus &#224; la CA en portant une armure.&lt;br /&gt;&lt;br /&gt;La prochaine impression de l’&lt;i&gt;Art de la guerre&lt;/i&gt; sera modifi&#233;e pour refl&#233;ter cette r&#232;gle.
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;/td&gt;
&lt;td&gt;&lt;img style=&quot;width:50px; cursor:pointer&quot; src=&quot;/wiki/public/upload/Illustrations/Wiki/faqbase1.png&quot; title=&quot;Cliquez pour afficher/cacher une FAQ officielle relative &#224; ce texte&quot; alt=&quot;Cliquez pour afficher/cacher l&#39;information&quot; onclick=&quot;
var cible = this.parentNode.previousSibling.previousSibling;
if (cible.style.display==&#39;none&#39;) {
  $(cible).show(&#39;slide&#39;);
  $(this).fadeTo(500,0.4);
} else {
  $(cible).hide(&#39;slide&#39;);
  $(this).fadeTo(500,1);
}&quot; ONMOUSEOVER=&quot;this.src = &#39;/wiki/public/upload/Illustrations/Wiki/faqalt1.png&#39;;&quot;
ONMOUSEOUT=&quot;this.src = &#39;/wiki/public/upload/Illustrations/Wiki/faqbase1.png&#39;;&quot; /&gt;
&lt;/td&gt;
&lt;/tr&gt;
&lt;/table&gt;
&lt;/div&gt;Le sohei est form&#233; au maniement de toutes les &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes#Armecourante.html&quot; title=&quot;armes courantes&quot;&gt;armes courantes&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques-Des-Armes#Armedeguerre.html&quot; title=&quot;armes de guerre&quot;&gt;de guerre&lt;/a&gt;, ainsi qu’au port des &lt;a class=&quot;pagelink&quot; href=&quot;Tableau-R&#233;capitulatif-Des-Armures#Legeres.html&quot; title=&quot;armure l&#233;g&#232;re&quot;&gt;armures l&#233;g&#232;res&lt;/a&gt;. Le sohei ne perd pas son aptitude de &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#DELUGEDECOUPS&quot; title=&quot;Le moine&quot;&gt;d&#233;luge de coups&lt;/a&gt; lorsqu&#39;il porte une armure l&#233;g&#232;re. Cette capacit&#233; modifie les formations en armes et armures du moine.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Don suppl&#233;mentaire&lt;a class=&quot;headeranchor&quot; id=&quot;Don_suppl&#233;mentaire_2&quot; href=&quot;#Don_suppl&#233;mentaire_2&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Le sohei peut choisir des dons de &lt;a class=&quot;pagelink&quot; href=&quot;Combat-Mont&#233;.html&quot; title=&quot;Combat mont&#233;&quot;&gt;combat mont&#233;&lt;/a&gt; comme &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#DONSUPPLEMENTAIRE&quot; title=&quot;Le moine&quot;&gt;dons suppl&#233;mentaires&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Gardien d&#233;vou&#233; (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Gardien_d&#233;vou&#233;_Ext_3&quot; href=&quot;#Gardien_d&#233;vou&#233;_Ext_3&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Niveau.html&quot; title=&quot;niveau&quot;&gt;niveau&lt;/a&gt; 1, le sohei peut toujours agir lors du &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;roulement-Dun-Combat#Roundsurprise.html&quot; title=&quot;round de surprise&quot;&gt;round de surprise&lt;/a&gt;, m&#234;me s’il ne rep&#232;re pas les ennemis. Dans ce cas, il est consid&#233;r&#233; comme &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Prisaud&#233;pourvu.html&quot; title=&quot;Pris au d&#233;pourvu&quot;&gt;pris au d&#233;pourvu&lt;/a&gt; jusqu’&#224; ce qu’il agisse. De plus, il gagne un bonus aux tests d’&lt;a class=&quot;pagelink&quot; href=&quot;D&#233;roulement-Dun-Combat#Initiative.html&quot; title=&quot;initiative&quot;&gt;initiative&lt;/a&gt; &#233;gal &#224; 1/2 niveau de moine. Au niveau 20, il fait automatiquement un 20 naturel au test d’initiative. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#COUPETOURDISSANT&quot; title=&quot;Le moine&quot;&gt;coup &#233;tourdissant&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Mains nues&lt;a class=&quot;headeranchor&quot; id=&quot;Mains_nues_4&quot; href=&quot;#Mains_nues_4&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Les d&#233;g&#226;ts des attaques &#224; mains nues du sohei n’augmentent pas, ni au niveau 4 ni par la suite.&lt;br /&gt;&lt;br /&gt;&lt;h3 class=&quot;separator&quot;&gt;Monture monastique (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Monture_monastique_Sur_5&quot; href=&quot;#Monture_monastique_Sur_5&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 4, le sohei peut d&#233;penser 1 point de &lt;a class=&quot;pagelink&quot; href=&quot;Moine#Reservedeki.html&quot; title=&quot;ki&quot;&gt;ki&lt;/a&gt; pour ajouter des points de vie suppl&#233;mentaires &#224; sa monture, pour un montant &#233;gal au double de son niveau, et ce pendant 1 heure par niveau. De plus, tant que le sohei et sa monture sont adjacents (y compris quand le sohei est en selle), la monture gagne les pouvoirs suivants (si le sohei en dispose) : &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#AMEDEDIAMANT&quot; title=&quot;Le moine&quot;&gt;&#226;me de diamant&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#BONUSALACA&quot; title=&quot;Le moine&quot;&gt;bonus &#224; la CA&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#ESQUIVEINSTINCTIVE&quot; title=&quot;Le moine&quot;&gt;esquive instinctive&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#ESQUIVESURNATURELLE&quot; title=&quot;Le moine&quot;&gt;esquive surnaturelle&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#FRAPPEKI&quot; title=&quot;Le moine&quot;&gt;frappe ki&lt;/a&gt; (tant que le sohei a au moins 1 point de ki dans sa r&#233;serve), &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#PERFECTIONDELETRE&quot; title=&quot;Le moine&quot;&gt;perfection de l’&#234;tre&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#SAUTPUISSANT&quot; title=&quot;Le moine&quot;&gt;sauts puissants&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#SERENITE&quot; title=&quot;Le moine&quot;&gt;s&#233;r&#233;nit&#233;&lt;/a&gt;. Quand le sohei d&#233;pense des points de sa r&#233;serve de ki, sa monture obtient les m&#234;mes avantages que lui. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#DEPLACEMENTACCELERE&quot; title=&quot;Le moine&quot;&gt;d&#233;placement acc&#233;l&#233;r&#233;&lt;/a&gt; et augmentation des d&#233;g&#226;ts &#224; mains nues.&lt;br /&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;Arme ki (Sur)&lt;a class=&quot;headeranchor&quot; id=&quot;Arme_ki_Sur_6&quot; href=&quot;#Arme_ki_Sur_6&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 4, le sohei peut, par une &lt;a class=&quot;pagelink&quot; href=&quot;Types-Dactions#Rapide.html&quot; title=&quot;Action rapide&quot;&gt;action rapide&lt;/a&gt;, d&#233;penser 1 point issu de sa &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#RESERVEDEKI&quot; title=&quot;Le moine&quot;&gt;r&#233;serve de ki&lt;/a&gt; pour donner un bonus d’alt&#233;ration de +1 &#224; ses jets d’attaque et de d&#233;g&#226;ts &#224; une arme (ou &#224; ses attaques &#224; mains nues). Ce bonus augmente de +1 tous les quatre niveaux apr&#232;s le 4, avec un bonus maximal de +5 au niveau 20. Le bonus persiste jusqu’&#224; la fin de son prochain tour. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#CHUTERALENTIE&quot; title=&quot;Le moine&quot;&gt;chute ralentie&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#PASCHASSE&quot; title=&quot;Le moine&quot;&gt;pas chass&#233;&lt;/a&gt;.&lt;br /&gt;&lt;br /&gt;
&lt;h3 class=&quot;separator&quot;&gt;Entra&#238;nement aux armes (Ext)&lt;a class=&quot;headeranchor&quot; id=&quot;Entra&#238;nement_aux_armes_Ext_7&quot; href=&quot;#Entra&#238;nement_aux_armes_Ext_7&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h3&gt;Au niveau 6, le sohei b&#233;n&#233;ficie de l’&lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html#ENTRAINEMENTAUXARMES&quot; title=&quot;Le guerrier&quot;&gt;entra&#238;nement aux armes&lt;/a&gt;, comme le &lt;a class=&quot;pagelink&quot; href=&quot;Guerrier.html&quot; title=&quot;Le guerrier&quot;&gt;guerrier&lt;/a&gt;, dans l’un des &lt;a class=&quot;pagelink&quot; href=&quot;Groupe-Darmes.html&quot; title=&quot;Les groupes d&amp;#39;arme du guerrier&quot;&gt;groupes&lt;/a&gt; suivants : arbal&#232;tes, arcs, armes d’hast, armes de jet, armes de moine ou lances. Il gagne un nouveau groupe tous les six niveaux apr&#232;s le 6, pour un maximum de trois groupes au niveau 18. Le sohei peut utiliser d&#233;luge de coups et frappe ki avec toutes les armes pour lesquelles il dispose d’un entra&#238;nement martial. Ce pouvoir remplace &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#CORPSDEDIAMANT&quot; title=&quot;Le moine&quot;&gt;corps de diamant&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#ETERNELLEJEUNESSE&quot; title=&quot;Le moine&quot;&gt;&#233;ternelle jeunesse&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#LANGUEDUSOLEILETDELALUNE&quot; title=&quot;Le moine&quot;&gt;langues du soleil et de la lune&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#PAUMEVIBRATOIRE&quot; title=&quot;Le moine&quot;&gt;paume vibratoire&lt;/a&gt; et &lt;a class=&quot;pagelink&quot; href=&quot;Moine.html#PURETEPHYSIQUE&quot; title=&quot;Le moine&quot;&gt;puret&#233; physique&lt;/a&gt;.
